function permutations(items) {
  const result = []
  const used = new Array(items.length).fill(false)

  function backtrack(path) {
    if (path.length === items.length) {
      result.push([...path])
      return
    }
    for (let index = 0; index < items.length; index++) {
      if (used[index]) continue
      used[index] = true
      path.push(items[index])
      backtrack(path)
      path.pop()
      used[index] = false
    }
  }

  backtrack([])
  return result
}

def combinations(items, size):
    result = []

    def backtrack(start, path):
        if len(path) == size:
            result.append(path.copy())
            return
        remaining = size - len(path)
        for index in range(start, len(items) - remaining + 1):
            path.append(items[index])
            backtrack(index + 1, path)
            path.pop()

    backtrack(0, [])
    return result

