function countNQueens(size) {
  const columns = new Set()
  const diagonalsDown = new Set()
  const diagonalsUp = new Set()

  function place(row) {
    if (row === size) return 1
    let solutions = 0
    for (let column = 0; column < size; column++) {
      const down = row - column
      const up = row + column
      if (columns.has(column) || diagonalsDown.has(down) || diagonalsUp.has(up)) continue
      columns.add(column)
      diagonalsDown.add(down)
      diagonalsUp.add(up)
      solutions += place(row + 1)
      columns.delete(column)
      diagonalsDown.delete(down)
      diagonalsUp.delete(up)
    }
    return solutions
  }

  return place(0)
}
